const _R2_KERNELS = (r2_1!, r2_2!, r2_3!, r2_4!, r2_5!, r2_6!, r2_7!, r2_8!, r2_9!, r2_10!)

"""
    r2_term(n, M, r0, r, f, fp, h1, dh1, ddh1, h2, dh2, ddh2, l3, m3, l1, m1, l2, m2, c;
            threaded=false)

The `n`-th quadratic second-order Ricci source term (`n ∈ 1:10`), evaluated on the radial grid `r` for
the coupling of first-order modes `(l1,m1)` and `(l2,m2)` into the target mode `(l3,m3)`. Host dispatcher
over the ten work-item kernels `r2_1!..r2_10!`: allocates the (pre-zeroed) output, then launches the
matching kernel. `h1,dh1,ddh1` / `h2,dh2,ddh2` are `Dict{NTuple{3,Int},Vector}` keyed `(i,l,m)` (the
`read_h1` layout): `h1`-family read at `(i,l1,m1)`, `h2`-family at `(i,l2,m2)`. An entirely absent
parent mode contributes the exact zero vector, as required by bilinearity. If any of `h`, `dh`, or
`ddh` supplies a component, that component must have `length(r)` entries; missing components retain
the zero-padding convention. Malformed present vectors throw `DimensionMismatch` before entering an
`@inbounds` kernel.

`c` is the PRECOMPUTED 3-harmonic angular coupling array for kernel `n`, ordered per
[`R2_COUPLING_SPEC`](@ref) (length-validated). Kernels carries no Wigner/3j machinery (design §5.5
purity); the canonical coupling-evaluating host wrapper is `SelfForce.SecondOrder.r2_term`, which
preserves the pre-hoist signature.

Returns a `Vector{ComplexF64}` of `length(r)`. `threaded=true` partitions the radial grid (≤20 chunks);
the result is bit-identical to the serial path.
"""
function r2_term(n::Integer, M, r0, r, f, fp,
                 h1, dh1, ddh1, h2, dh2, ddh2,
                 l3::Integer, m3::Integer, l1::Integer, m1::Integer, l2::Integer, m2::Integer,
                 c::AbstractVector{<:Real};
                 threaded::Bool = false)
    (1 <= n <= 10) || error("Kernels.r2_term: kernel R2_$n out of range (have 1:10)")
    length(c) == length(R2_COUPLING_SPEC[n]) ||
        throw(ArgumentError("Kernels.r2_term: kernel R2_$n needs length(c) == " *
                            "$(length(R2_COUPLING_SPEC[n])) couplings (R2_COUPLING_SPEC[$n]), " *
                            "got $(length(c))"))
    ricci = zeros(ComplexF64, length(r))
    have1 = _has_mode(h1, dh1, ddh1, l1, m1)
    have2 = _has_mode(h2, dh2, ddh2, l2, m2)
    (have1 && have2) || return ricci
    return _R2_KERNELS[n](ricci, M, r0, r, f, fp, h1, dh1, ddh1, h2, dh2, ddh2,
                          l3, m3, l1, m1, l2, m2, c; threaded = threaded)
end
